import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"7、【師】 坎下坤上","description":"周易尚氏學 - 7、【師】 坎下坤上","frontmatter":{"title":"7、【師】 坎下坤上","description":"周易尚氏學 - 7、【師】 坎下坤上"},"headers":[],"relativePath":"classics/shangshi/012.md","filePath":"classics/shangshi/012.md"}'),s={name:"classics/shangshi/012.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_7、【師】-坎下坤上" tabindex="-1">7、【師】 坎下坤上 <a class="header-anchor" href="#_7、【師】-坎下坤上" aria-label="Permalink to “7、【師】 坎下坤上”">​</a></h1><p>師。眾也。坤舍於坎。俱居子方。坤坎皆為眾。故曰師。猶乾舍於離。俱居午為同人也。貞。卜問也。大人。正義作丈人。子夏傳作大人。崔憬李鼎祚從之是也。此與困貞大人吉同。皆謂二。乾九二雲。利見大人。利見故吉。陸績鄭王等皆讀為丈。謂震為長子。丈者長也。故曰丈人。豈知二得中。臨御萬民。大人之事。以二為大人。於象方合。丈人則於卦名不類矣。陸謂丈人為聖人。王謂丈人為莊嚴之稱。皆曲說也。且子夏傳為韓嬰所作。(臧庸據七略。謂嬰字子夏。今按藝文志有韓氏二篇。注曰名嬰。其篇數與隋唐志子夏傳卷數同。疑即子夏傳。)與田何同時。皆秦遺老。其所據當無誤也。</p><p>象曰。師眾也。貞正也。能以眾正。可以王矣。剛中而應。行險而順。以此毒天下而民從之。吉又何咎矣。</p><p>震為帝為王。故曰可以王。二應五。坎險坤順。震為行。故曰行險而順。易林以坤為害。坎為毒。震為從。乾寶雲。毒荼苦也。按列子宋陽裡華子病忘。闔室毒之。注毒苦也。師旅之興。不無所苦。然非師旅不能安天下。故民從之而吉也。吳語云。吾先君闔廬，以與楚昭王毒逐於中原柏舉。義與此同也。馬融訓毒為治。與行險而順。義不相應。行險即毒。順即民從也。他若王弼之訓毒為役。崔憬訓為亭毒。俞樾訓為督。皆不協。是皆因坎毒之象。人不盡知。故眾說紛紜也。豈知噬嗑六三雲。遇毒。以坎為毒。象甚明也。</p><p>象曰。地中有水。師。君子以容民畜眾。</p><p>地中所容畜。莫多於水。故君子法之。</p><p>初六。師出以律。否臧兇。</p><p>坎為律。律法也。臧善也。否臧。即失律也。失律故兇。</p><h3 id="象曰。師出以律。失律兇也。" tabindex="-1">象曰。師出以律。失律兇也。 <a class="header-anchor" href="#象曰。師出以律。失律兇也。" aria-label="Permalink to “象曰。師出以律。失律兇也。”">​</a></h3><p>坎為失。故曰失律。</p><p>九二。在師中吉。無咎。王三錫命。</p><p>居下卦之中。故曰在師中吉。失位宜有咎。在師中。故無咎。震為王為言。故曰命。震數三。錫予也。王三錫命者。言王以官爵或車服器物。錫予有功。而告命之也。曲禮一命受爵。二命受服。三命受車馬。言二為卦主。撫馭萬邦。而日有所錫予也。舊解謂六五為君。錫命於二。於卦義全背。祇荀爽謂王指二為得解。</p><h3 id="象曰。在師中吉。承天寵也。王三錫命。懷萬邦也。" tabindex="-1">象曰。在師中吉。承天寵也。王三錫命。懷萬邦也。 <a class="header-anchor" href="#象曰。在師中吉。承天寵也。王三錫命。懷萬邦也。" aria-label="Permalink to “象曰。在師中吉。承天寵也。王三錫命。懷萬邦也。”">​</a></h3><p>五天位。言二必升五。為群陰所承也。故曰承天寵。坤為萬邦。言二臨萬邦。而有所錫予者。正所以懷念萬邦。坎為懷也。故夫舊解謂六五錫二者。不惟於經背。於象傳亦背矣。</p><p>六三。師或輿尸。兇。坎為屍。</p><p>震為輿。管輅以坎為棺槨。故曰輿尸。夫陳師而出。。輿尸以還。其無功甚矣。故曰兇。蓋坤為死。三失位無應。以陰遇陰。得敵。故兇如是。</p><h3 id="象曰。師或輿尸。大無功也。" tabindex="-1">象曰。師或輿尸。大無功也。 <a class="header-anchor" href="#象曰。師或輿尸。大無功也。" aria-label="Permalink to “象曰。師或輿尸。大無功也。”">​</a></h3><p>大無功。即太無功。</p><p>六四。師左次。無咎。</p><p>次舍也。震為左。故曰左次。古人尚右。左次則退也。四前臨重陰。陰遇陰得敵。其行難矣。知難而退。故無咎也。</p><h3 id="象曰。左次無咎。未失常也。" tabindex="-1">象曰。左次無咎。未失常也。 <a class="header-anchor" href="#象曰。左次無咎。未失常也。" aria-label="Permalink to “象曰。左次無咎。未失常也。”">​</a></h3><p>未失常者。言四當位。量力自處。故不改其常。</p><p>六五。田有禽。利執言。無咎。長子帥師。弟子輿尸。貞兇。</p><p>田獵。禽獲也。釋文雲。徐本作擒。王陶廬雲。說文無擒字。其見於經傳者。皆作禽。展獲字禽。不從手。是其證。下應二陽故有禽獲。二震為言。利執言者。言師出有名。如湯武歷數桀紂之罪。漢高討殺懷王者是也。故無咎。五應二。二震主爻。震長子。居師中為主。故曰長子帥師。二亦坎主爻。坎為震弟為屍。故曰弟子輿尸。輿尸故貞兇。貞卜問也。言五宜與震。不宜與坎。與坎。則使不當矣。</p><h3 id="象曰。長子帥師。以中行也。弟子輿尸。使不當也。" tabindex="-1">象曰。長子帥師。以中行也。弟子輿尸。使不當也。 <a class="header-anchor" href="#象曰。長子帥師。以中行也。弟子輿尸。使不當也。" aria-label="Permalink to “象曰。長子帥師。以中行也。弟子輿尸。使不當也。”">​</a></h3><p>二居中為震主。故為群陰之帥。二坎陷於陰中。不可使。使則有輿尸之禍也。宋衷虞翻謂弟子指六三。非是。皆因三爻有輿尸字而誤。</p><p>上六。大君有命。開國承家。小人勿用。</p><p>大君指二震。震為君為言。故曰大君有命。坤為國。二升五居坤中。故曰開國。坎為室為家。二升五仍坎體。群陰承之。故曰承家。小人指上六。二升五雖開國承家。上六獨居五後。乘陽勢逆。不順承五。比之後夫兇。即此爻也。故戒曰勿用。宋衷虞翻解開國承家是矣。然二升五於上六何涉。即以勿用為戒。必有故也。不申其故。只以坤為小人。籠統說之。胡可乎。惠棟知其不安。仍不能得其故。竟謂小人指初三。益淆亂矣。</p><h3 id="象曰。大君有命。以正功也。小人勿用。必亂邦也。" tabindex="-1">象曰。大君有命。以正功也。小人勿用。必亂邦也。 <a class="header-anchor" href="#象曰。大君有命。以正功也。小人勿用。必亂邦也。" aria-label="Permalink to “象曰。大君有命。以正功也。小人勿用。必亂邦也。”">​</a></h3><p>二升五位正。故曰正功。坤為邦為亂。上六反君道。故曰必亂邦。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
